"""Screenshot storage. Files are validated by content and stored under random names."""

from __future__ import annotations

import re
import uuid
from pathlib import Path

from .i18n import tr

# Stored names are generated by us, so anything else is rejected outright.
SAFE_NAME = re.compile(r"^[a-f0-9]{32}\.(png|jpg|gif|webp)$")


class UploadError(ValueError):
    pass


def detect_image_type(head: bytes) -> str | None:
    """Identify PNG/JPEG/GIF/WebP from magic bytes (SVG is deliberately excluded)."""
    if head.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"
    if head.startswith(b"\xff\xd8\xff"):
        return "jpg"
    if head[:6] in (b"GIF87a", b"GIF89a"):
        return "gif"
    if head[:4] == b"RIFF" and head[8:12] == b"WEBP":
        return "webp"
    return None


def save_image(uploads_dir: Path, data: bytes, max_bytes: int) -> str:
    if not data:
        raise UploadError(tr("The uploaded file is empty"))
    if len(data) > max_bytes:
        raise UploadError(tr("Image exceeds the {limit} MB limit", limit=max_bytes // (1024 * 1024)))
    kind = detect_image_type(data[:16])
    if kind is None:
        raise UploadError(tr("Only PNG, JPEG, GIF and WebP images are supported"))
    filename = f"{uuid.uuid4().hex}.{kind}"
    (uploads_dir / filename).write_bytes(data)
    return filename


def is_safe_name(filename: str) -> bool:
    return bool(SAFE_NAME.match(filename))


def delete_file(uploads_dir: Path, filename: str) -> None:
    if is_safe_name(filename):
        (uploads_dir / filename).unlink(missing_ok=True)
